import{_ as a,o,c as s,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const t="/images/admin/productos-lista.webp",n="/images/admin/producto-nuevo.webp",c="/images/admin/producto-variantes.webp",v=JSON.parse('{"title":"3. Cómo Agregar y Editar Productos en la Tienda","description":"","frontmatter":{},"headers":[],"relativePath":"admin/productos.md","filePath":"admin/productos.md"}'),d={name:"admin/productos.md"};function i(l,e,u,p,m,h){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="_3-como-agregar-y-editar-productos-en-la-tienda" tabindex="-1">3. Cómo Agregar y Editar Productos en la Tienda <a class="header-anchor" href="#_3-como-agregar-y-editar-productos-en-la-tienda" aria-label="Permalink to &quot;3. Cómo Agregar y Editar Productos en la Tienda&quot;">​</a></h1><p>Desde el módulo de <strong>Productos</strong> (<a href="https://pyme.rsfsecure.site/admin/productos" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/productos</a>) puedes subir nuevos artículos, ponerles fotos, fijar precios, asignar el impuesto del 7% y crear opciones de colores o tallas.</p><hr><h2 id="_3-1-lista-general-de-productos" tabindex="-1">3.1 Lista General de Productos <a class="header-anchor" href="#_3-1-lista-general-de-productos" aria-label="Permalink to &quot;3.1 Lista General de Productos&quot;">​</a></h2><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Catálogo General de Productos en Administración</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/productos</span></div><div class="screenshot-body"><img src="'+t+'" alt="Catálogo General de Productos en Administración" loading="lazy" decoding="async"></div></div><h3 id="que-puedes-hacer-en-esta-lista" tabindex="-1">Qué puedes hacer en esta lista: <a class="header-anchor" href="#que-puedes-hacer-en-esta-lista" aria-label="Permalink to &quot;Qué puedes hacer en esta lista:&quot;">​</a></h3><ul><li><strong>Buscar un producto:</strong> Escribe su nombre o código en el buscador para encontrarlo al instante.</li><li><strong>Filtrar por categoría o marca:</strong> Para ver por ejemplo solo los celulares o solo artículos de una marca específica.</li><li><strong>Ver existencias:</strong> Un punto verde indica stock saludable; un punto rojo indica que el producto se agotó.</li></ul><hr><h2 id="_3-2-como-dar-de-alta-un-producto-nuevo-paso-a-paso" tabindex="-1">3.2 Cómo dar de alta un Producto Nuevo (Paso a Paso) <a class="header-anchor" href="#_3-2-como-dar-de-alta-un-producto-nuevo-paso-a-paso" aria-label="Permalink to &quot;3.2 Cómo dar de alta un Producto Nuevo (Paso a Paso)&quot;">​</a></h2><p>Para subir un artículo nuevo, haz clic en el botón verde <strong>&quot;+ Nuevo Producto&quot;</strong> en la esquina superior derecha (<a href="https://pyme.rsfsecure.site/admin/productos/create" target="_blank" rel="noreferrer">https://pyme.rsfsecure.site/admin/productos/create</a>):</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Formulario de Creación de Producto</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/productos/create</span></div><div class="screenshot-body"><img src="'+n+'" alt="Formulario de Creación de Producto" loading="lazy" decoding="async"></div></div><h3 id="campos-que-debes-completar" tabindex="-1">Campos que debes completar: <a class="header-anchor" href="#campos-que-debes-completar" aria-label="Permalink to &quot;Campos que debes completar:&quot;">​</a></h3><ol><li><strong>Nombre del Producto:</strong> Escribe un nombre claro y atractivo (ej. <em>&quot;GoPro HERO12 Black - Cámara de Acción 5.3K&quot;</em>).</li><li><strong>Marca y Categoría:</strong> Selecciona a qué departamento pertenece.</li><li><strong>Precio de Venta:</strong> El precio normal en dólares (ej. <code>$399.00</code>).</li><li><strong>Precio de Oferta (Opcional):</strong> Si quieres ponerlo en descuento, escribe aquí el precio rebajado (ej. <code>$349.00</code>). La tienda mostrará automáticamente la insignia de oferta con el porcentaje de ahorro.</li><li><strong>Impuesto:</strong> Selecciona <strong>7% ITBMS</strong> para que el sistema desglose el impuesto en la factura.</li><li><strong>Subir Fotografías:</strong> Arrastra o selecciona las fotos del producto desde tu computadora. El sistema las optimizará automáticamente para que carguen al instante.</li><li>Haz clic en <strong>&quot;Guardar Producto&quot;</strong>.</li></ol><hr><h2 id="_3-3-productos-con-variantes-colores-tallas-o-capacidad" tabindex="-1">3.3 Productos con Variantes (Colores, Tallas o Capacidad) <a class="header-anchor" href="#_3-3-productos-con-variantes-colores-tallas-o-capacidad" aria-label="Permalink to &quot;3.3 Productos con Variantes (Colores, Tallas o Capacidad)&quot;">​</a></h2><p>Si un producto tiene diferentes opciones (por ejemplo: memoria de 128GB o 256GB, o camiseta en blanco o negro):</p><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Opciones de Colores, Tallas y Variantes</span><span class="screenshot-url">https://pyme.rsfsecure.site/admin/productos/.../variantes</span></div><div class="screenshot-body"><img src="'+c+'" alt="Opciones de Colores, Tallas y Variantes" loading="lazy" decoding="async"></div></div><ol><li>En el producto entra a la pestaña <strong>&quot;Variantes&quot;</strong>.</li><li>Agrega las opciones que manejas (ej. Color: <em>Azul, Negro</em>; Talla: <em>S, M, L</em>).</li><li>Podrás poner un precio diferente y un inventario independiente a cada opción (ejemplo: la versión de 256GB cuesta $50 más que la de 128GB).</li></ol>',18)])])}const b=a(d,[["render",i]]);export{v as __pageData,b as default};
